META = {'file': 'index.html', 'path': '', 'current': '', 'title': 'Saas Projects | Ondernemen met vakmanschap', 'description': 'Saas Projects is de thuisbasis van meerdere ondernemingen: webwinkels, verkoop via bol.com, kozijnmontage door heel Nederland en fietsenwinkel VanWiel.', 'ld': {'@context': 'https://schema.org', '@type': 'Organization', 'name': 'Saas Projects', 'url': 'https://saasprojects.nl/', 'logo': 'https://saasprojects.nl/assets/img/logo.png', 'email': 'info@saasprojects.nl', 'telephone': '+31626889789', 'vatID': 'NL003577672B78', 'founder': {'@type': 'Person', 'name': 'Yannick Saas', 'jobTitle': 'Oprichter', 'image': 'https://saasprojects.nl/assets/img/ondernemer.webp'}, 'address': {'@type': 'PostalAddress', 'streetAddress': 'Hallenweg 16', 'postalCode': '5683 CT', 'addressLocality': 'Best', 'addressCountry': 'NL'}, 'subOrganization': [{'@type': 'HomeAndConstructionBusiness', 'name': 'Saas Projects Kozijnen', 'url': 'https://saasprojects.nl/kozijnen'}, {'@type': 'OnlineStore', 'name': 'VanWiel', 'url': 'https://vanwiel.nl'}]}}

BODY = '    <section class="hero">\n      <div class="hero__text">\n        <span class="label">Saas Projects</span>\n        <h1>Ondernemen met <em>vakmanschap.</em></h1>\n        <p class="hero__lede">Eén ondernemer, meerdere bedrijven. Van webwinkels en bol.com tot kozijnmontage door heel Nederland en een eigen fietsenwinkel, gebouwd op kwaliteit en afspraken die we nakomen.</p>\n        <div class="hero__ctas">\n          <a class="btn" href="#ondernemingen">Ontdek de ondernemingen</a>\n          <a class="btn btn--outline" href="#contact">Neem contact op</a>\n        </div>\n      </div>\n      <div class="hero__visual" aria-hidden="true"><div class="hero__art"><span class="hero__grid"></span><span class="hero__glow"></span><span class="hero__house"></span></div></div>\n    </section>\n    <div class="usp"><div class="container"><ul><li>Dropshipping-webwinkels</li><li>Verkooppartner bol.com</li><li>Kozijnen door heel Nederland</li><li>Fietsenwinkel VanWiel</li></ul></div></div>\n\n    <section class="section">\n      <div class="container">\n        <div class="statement">\n          <span class="label reveal">Over Saas Projects</span>\n          <h2 class="reveal">Wat begon met één webwinkel, groeide uit tot een <em>familie van bedrijven</em>, online én op de bouwplaats, elk met dezelfde toewijding aan kwaliteit.</h2>\n        </div>\n        <div class="facts reveal">\n          <div class="fact"><strong>05</strong><span>Ondernemingen</span></div>\n          <div class="fact"><strong>1500+</strong><span>Kozijnen geplaatst</span></div>\n          <div class="fact"><strong>6</strong><span>Jaar ervaring</span></div>\n        </div>\n      </div>\n    </section>\n\n    <section class="section section--paper" id="ondernemingen">\n      <div class="container">\n        <div class="section-head">\n          <div class="reveal">\n            <span class="label">Ondernemingen</span>\n            <h2>Vijf bedrijven, <em>één standaard.</em></h2>\n          </div>\n          <p class="lede reveal" style="max-width:26em;margin:0">Elk bedrijf heeft een eigen vak en een eigen klant. Wat ze delen is de manier van werken.</p>\n        </div>\n\n        <ol class="ventures">\n          <li class="venture venture--link reveal">\n\n            <div>\n              <span class="venture__kind">Dropshipping</span>\n              <h3><a href="webwinkels.html">Webwinkels</a></h3>\n            </div>\n            <p>Een groeiende reeks dropshipping-webwinkels, elk gericht op een eigen niche. Producten gaan rechtstreeks van de leverancier naar de klant, zodat we snel kunnen inspelen op wat klanten zoeken.</p>\n            <div class="venture__cta"><a class="link" href="webwinkels.html">Bekijk <svg aria-hidden="true"><use href="assets/icons.svg#arrow"/></svg></a></div>\n          </li>\n          <li class="venture venture--link reveal">\n\n            <div>\n              <span class="venture__kind">Verkooppartner bol.com</span>\n              <h3><a href="bol.html">Huis, tuin &amp; keuken</a></h3>\n            </div>\n            <div class="venture__desc">\n              <p>Via bol.com verkopen we zorgvuldig geselecteerde producten voor in en om het huis, aan klanten in Nederland en België.</p>\n              <div class="venture__tags"><span>Wonen</span><span>Tuin</span><span>Keuken</span></div>\n            </div>\n            <div class="venture__cta"><a class="link" href="bol.html">Bekijk <svg aria-hidden="true"><use href="assets/icons.svg#arrow"/></svg></a></div>\n          </li>\n          <li class="venture venture--link reveal">\n\n            <div>\n              <span class="venture__kind">Bouw &amp; montage</span>\n              <h3><a href="kozijnen.html">Saas Projects Kozijnen</a></h3>\n            </div>\n            <p>Montage van kunststof en aluminium kozijnen en renovatie van bestaande woningen, door heel Nederland. Nauwkeurig ingemeten, strak geplaatst en netjes opgeleverd.</p>\n            <div class="venture__cta"><a class="link" href="kozijnen.html">Bekijk <svg aria-hidden="true"><use href="assets/icons.svg#arrow"/></svg></a></div>\n          </li>\n          <li class="venture venture--link reveal">\n\n            <div>\n              <span class="venture__kind">Online fietsenwinkel</span>\n              <h3><a href="vanwiel.html">VanWiel</a></h3>\n            </div>\n            <p>Onze eigen online fietsenwinkel voor fietsen, e-bikes en accessoires, in Nederland, België, Duitsland, Frankrijk en Oostenrijk.</p>\n            <div class="venture__cta"><a class="link" href="vanwiel.html">Bekijk <svg aria-hidden="true"><use href="assets/icons.svg#arrow"/></svg></a></div>\n          </li>\n          <li class="venture venture--soon reveal">\n\n            <div>\n              <span class="venture__kind">In ontwikkeling</span>\n              <h3>Nieuw project</h3>\n            </div>\n            <p>Achter de schermen werken we aan een vijfde onderneming. Meer daarover maken we binnenkort bekend.</p>\n            <div class="venture__cta"><span class="soon">Binnenkort</span></div>\n          </li>\n        </ol>\n      </div>\n    </section>\n\n    <section class="section" id="verhaal">\n      <div class="container story">\n        <div class="reveal">\n          <div class="portrait">\n            <img src="assets/img/ondernemer.webp" alt="Yannick Saas, oprichter van Saas Projects" width="576" height="720" loading="lazy">\n          </div>\n          <p class="portrait__cap">Yannick Saas · Oprichter</p>\n        </div>\n        <div class="reveal">\n          <span class="label">Het verhaal</span>\n          <h2>Van webwinkel tot <em>bouwplaats.</em></h2>\n          <p>Ik ben begonnen achter een laptop, met een eerste webwinkel. Daar leerde ik wat ondernemen werkelijk betekent: een klant die online bestelt, vertrouwt je zonder je ooit te hebben ontmoet. Dat vertrouwen verdien je met eerlijke informatie, goede producten en afspraken die je nakomt.</p>\n          <blockquote class="quote">“Elk bedrijf is anders. De standaard blijft dezelfde.”</blockquote>\n          <p>Na de webwinkels volgde bol.com, en daarna een stap die weinig mensen verwachtten: de bouw in, met de montage van kozijnen door heel Nederland. Met VanWiel kwam er een eigen fietsenwinkel bij, en het volgende project staat al in de steigers.</p>\n          <p>De basis is overal gelijk: goede producten, eerlijke prijzen en persoonlijk contact.</p>\n          <div class="signature"><b>Yannick Saas</b><span>Oprichter, Saas Projects</span></div>\n          <a class="link" href="over.html" style="margin-top:36px">Lees het hele verhaal <svg aria-hidden="true"><use href="assets/icons.svg#arrow"/></svg></a>\n        </div>\n      </div>\n    </section>\n\n    <section class="section section--night">\n      <div class="container">\n        <div class="section-head" style="margin-bottom:0">\n          <div class="reveal">\n            <span class="label">Waar we voor staan</span>\n            <h2>Drie principes, <em>zonder uitzondering.</em></h2>\n          </div>\n        </div>\n        <div class="principles">\n          <div class="principle reveal"><h3>Betrouwbaar</h3><p>Duidelijke afspraken, en die ook nakomen. Of het nu gaat om een montage of een pakket.</p></div>\n          <div class="principle reveal"><h3>Kwaliteit</h3><p>Vakmanschap op de bouwplaats en zorgvuldig geselecteerde producten in onze winkels.</p></div>\n          <div class="principle reveal"><h3>Persoonlijk</h3><p>Korte lijnen en één aanspreekpunt. U spreekt direct met de ondernemer.</p></div>\n        </div>\n      </div>\n    </section>\n\n    <section class="section" id="contact">\n      <div class="container contact">\n        <div class="reveal">\n          <span class="label">Contact</span>\n          <h2>Neem <em>contact</em> op.</h2>\n          <p class="lede">Een vraag over een van de bedrijven, een zakelijk voorstel of interesse in samenwerking? Laat het weten. U hoort snel van mij.</p>\n          <ul class="details">\n            <li><small>Telefoon</small><a href="tel:+31626889789">06-26889789</a></li>\n            <li><small>WhatsApp</small><a href="https://wa.me/31626889789" rel="noopener">Stuur een bericht</a></li>\n            <li><small>E-mail</small><a href="mailto:info@saasprojects.nl">info@saasprojects.nl</a></li>\n            <li><small>Adres</small><span>Hallenweg 16, 5683 CT Best<br><span class="addr-note">Geen bezoekadres</span></span></li>\n          </ul>\n        </div>\n\n        <form class="form reveal" name="contact" method="POST" action="https://api.web3forms.com/submit">\n          <input type="hidden" name="access_key" value="__WEB3FORMS_KEY__">\n          <input type="hidden" name="subject" value="Nieuw bericht via saasprojects.nl (contact)">\n          <input type="hidden" name="from_name" value="saasprojects.nl">\n          <input type="hidden" name="redirect" value="https://saasprojects.nl/bedankt.html">\n          <input type="checkbox" name="botcheck" class="hidden" tabindex="-1" autocomplete="off" aria-hidden="true">\n          <div class="row">\n            <div class="field"><label for="naam">Naam</label><input id="naam" name="naam" autocomplete="name" required></div>\n            <div class="field"><label for="email">E-mail</label><input id="email" name="email" type="email" autocomplete="email" required></div>\n          </div>\n          <div class="field">\n            <label for="onderwerp">Onderwerp</label>\n            <select id="onderwerp" name="onderwerp">\n              <option>Webwinkels</option>\n              <option>Bol.com-winkel</option>\n              <option>Kozijnen &amp; renovatie</option>\n              <option>VanWiel</option>\n              <option>Samenwerking</option>\n              <option>Overig</option>\n            </select>\n          </div>\n          <div class="field"><label for="bericht">Bericht</label><textarea id="bericht" name="bericht" required></textarea></div>\n          <label class="check"><input type="checkbox" name="akkoord" required> <span>Ik ga akkoord dat mijn gegevens worden gebruikt om contact met mij op te nemen, zoals beschreven in het <a href="privacybeleid.html">privacybeleid</a>.</span></label>\n          <button class="btn" type="submit">Verstuur bericht <svg aria-hidden="true"><use href="assets/icons.svg#arrow"/></svg></button>\n        </form>\n      </div>\n    </section>'
